CREATE TABLE rg_readings (device_id STRING, sensor_type STRING, reading DOUBLE) WITH ('connector'='faker','rows-per-second'='3','fields.device_id.expression'='#{Options.option ''dev-A'',''dev-B'',''dev-C''}','fields.sensor_type.expression'='#{Options.option ''temperature'',''humidity'',''pressure''}','fields.reading.expression'='#{Number.randomDouble ''2'',''0'',''1100''}');
CREATE TABLE rg_processed (event_kind STRING, device_id STRING, sensor_type STRING, raw_value DOUBLE, `value` DOUBLE, unit STRING, alert BOOLEAN, rule_id STRING, rule_version BIGINT, action STRING, fire_count BIGINT, first_fired BIGINT, event_ts BIGINT, status STRING, device_seen BIGINT) WITH ('value.format'='json-registry','kafka.retention.time'='1 d');
